import{_ as l,c as e,o as a,ag as o}from"./chunks/framework.bCALENAD.js";const u=JSON.parse('{"title":"Java 基础入门与核心语法","description":"","frontmatter":{},"headers":[],"relativePath":"notes/java/base.md","filePath":"notes/java/base.md","lastUpdated":1784345102000}'),d={name:"notes/java/base.md"};function i(n,t,s,r,c,g){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="java-基础入门与核心语法" tabindex="-1">Java 基础入门与核心语法 <a class="header-anchor" href="#java-基础入门与核心语法" aria-label="Permalink to &quot;Java 基础入门与核心语法&quot;">​</a></h1><h2 id="语言总览" tabindex="-1">语言总览 <a class="header-anchor" href="#语言总览" aria-label="Permalink to &quot;语言总览&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">跨平台原理</p><ul><li><strong>核心机制</strong>：Java 能够在不同的操作系统上运行，依赖于在操作系统上安装对应的 <strong>Java 虚拟机</strong>。</li><li><strong>作用</strong>：JVM 屏蔽了底层操作系统的差异，实现了“一次编写，到处运行”。</li></ul></div><div class="info custom-block"><p class="custom-block-title">JRE 和 JDK</p><p><strong>JRE</strong></p><ul><li><strong>定义</strong>：Java 程序运行时的环境。</li><li><strong>组成</strong>：包含 JVM 和需要的核心类库。</li><li><strong>用途</strong>：如果只需要运行一个已有的 Java 程序，只需安装 JRE 即可。</li></ul><p><strong>JDK</strong></p><ul><li><strong>定义</strong>：Java 程序开发工具包。</li><li><strong>组成</strong>：包含 JRE + 开发人员使用的工具。</li><li><strong>关键工具</strong>：编译工具 <code>javac.exe</code> 和运行工具 <code>java.exe</code>。</li><li><strong>用途</strong>：想要开发一个 Java 程序，必须安装 JDK。</li></ul></div><div class="info custom-block"><p class="custom-block-title">Java 程序开发运行流程</p><ol><li><p>编写程序</p><ul><li>开发者编写源代码文件（<code>.java</code> 文件）。</li></ul></li><li><p>编译程序</p><ul><li>使用 <code>javac</code> 命令进行编译。</li><li><strong>产物</strong>：得到字节码文件（<code>.class</code> 文件），这是与平台无关的中间代码。</li></ul></li><li><p>运行程序</p><ul><li>使用 <code>java</code> 命令启动 JVM 加载并执行字节码文件。</li></ul></li></ol></div><h2 id="二、基本概念" tabindex="-1">二、基本概念 <a class="header-anchor" href="#二、基本概念" aria-label="Permalink to &quot;二、基本概念&quot;">​</a></h2><h3 id="常量" tabindex="-1">常量 <a class="header-anchor" href="#常量" aria-label="Permalink to &quot;常量&quot;">​</a></h3><p><strong>定义</strong>：在程序运行中，其值不可发生改变的量。</p><table tabindex="0"><thead><tr><th style="text-align:left;">常量类型</th><th style="text-align:left;">说明</th><th style="text-align:left;">举例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>字符串常量</strong></td><td style="text-align:left;">用双引号括起来的内容</td><td style="text-align:left;"><code>&quot;HelloWorld&quot;</code>, <code>&quot;程序员&quot;</code></td></tr><tr><td style="text-align:left;"><strong>整数常量</strong></td><td style="text-align:left;">不带小数的数字</td><td style="text-align:left;"><code>666</code>, <code>-88</code></td></tr><tr><td style="text-align:left;"><strong>小数常量</strong></td><td style="text-align:left;">带小数的数字</td><td style="text-align:left;"><code>13.14</code>, <code>-5.21</code></td></tr><tr><td style="text-align:left;"><strong>字符常量</strong></td><td style="text-align:left;">用单引号括起来的内容</td><td style="text-align:left;"><code>&#39;A&#39;</code>, <code>&#39;0&#39;</code>, <code>&#39;我&#39;</code></td></tr><tr><td style="text-align:left;"><strong>布尔常量</strong></td><td style="text-align:left;">布尔值，表示真假</td><td style="text-align:left;">只有两个值：<code>true</code>, <code>false</code></td></tr><tr><td style="text-align:left;"><strong>空常量</strong></td><td style="text-align:left;">一个特殊的值，空值</td><td style="text-align:left;">值是：<code>null</code></td></tr></tbody></table><h3 id="数据类型" tabindex="-1">数据类型 <a class="header-anchor" href="#数据类型" aria-label="Permalink to &quot;数据类型&quot;">​</a></h3><p>Java 是强类型语言，每种数据都有明确的类型，占用不同的内存空间。</p><div class="info custom-block"><p class="custom-block-title">数据类型分类</p><ul><li><strong>基本数据类型</strong>： <ul><li><strong>数值型</strong>： <ul><li>整数 (<code>byte</code>, <code>short</code>, <code>int</code>, <code>long</code>)</li><li>浮点数 (<code>float</code>, <code>double</code>)</li></ul></li><li><strong>非数值型</strong>： <ul><li>字符 (<code>char</code>)</li><li>布尔 (<code>boolean</code>)</li></ul></li></ul></li><li><strong>引用数据类型</strong>： <ul><li>类 (<code>class</code>)</li><li>接口 (<code>interface</code>)</li><li>数组 (<code>[]</code>)</li></ul></li></ul></div><div class="info custom-block"><p class="custom-block-title">基本数据类型详情表</p><table tabindex="0"><thead><tr><th style="text-align:left;">数据类型</th><th style="text-align:left;">关键字</th><th style="text-align:left;">内存占用</th><th style="text-align:left;">取值范围</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>整数</strong></td><td style="text-align:left;">byte</td><td style="text-align:left;">1</td><td style="text-align:left;">-128 ~ 127</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">short</td><td style="text-align:left;">2</td><td style="text-align:left;">-32768 ~ 32767</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"><strong>int (默认)</strong></td><td style="text-align:left;">4</td><td style="text-align:left;">-2的31次方到2的31次方-1</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">long</td><td style="text-align:left;">8</td><td style="text-align:left;">-2的63次方到2的63次方-1</td></tr><tr><td style="text-align:left;"><strong>浮点数</strong></td><td style="text-align:left;">float</td><td style="text-align:left;">4</td><td style="text-align:left;">负数: -3.402823E+38到-1.401298E-45; 正数: 1.401298E-45到3.402823E+38</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"><strong>double (默认)</strong></td><td style="text-align:left;">8</td><td style="text-align:left;">负数: -1.797693E+308到-4.9000000E-324; 正数: 4.9000000E-324到1.797693E+308</td></tr><tr><td style="text-align:left;"><strong>字符</strong></td><td style="text-align:left;">char</td><td style="text-align:left;">2</td><td style="text-align:left;">0-65535</td></tr><tr><td style="text-align:left;"><strong>布尔</strong></td><td style="text-align:left;">boolean</td><td style="text-align:left;">1</td><td style="text-align:left;">true, false</td></tr></tbody></table></div><h3 id="变量" tabindex="-1">变量 <a class="header-anchor" href="#变量" aria-label="Permalink to &quot;变量&quot;">​</a></h3><ul><li><strong>概念</strong>：内存中的一个存储区域（在程序运行过程中，其值可以发生改变）。</li><li><strong>格式</strong>：<code>数据类型 变量名 = 值;</code> （实例：<code>int a = 10;</code>）</li><li><strong>注意事项</strong>： <ul><li>在 Java 中，变量必须先定义后使用，仅定义不赋值的话使用会报错。</li><li><code>Long</code> 型的结尾需要加 <code>L</code>。</li><li>对于 <code>float</code> 类型，需要加上 <code>f</code> 后缀。</li></ul></li></ul><h3 id="类型转换" tabindex="-1">类型转换 <a class="header-anchor" href="#类型转换" aria-label="Permalink to &quot;类型转换&quot;">​</a></h3><ul><li>4.1 自动类型转换</li><li>4.2 强制类型转换</li></ul><h3 id="运算符" tabindex="-1">运算符 <a class="header-anchor" href="#运算符" aria-label="Permalink to &quot;运算符&quot;">​</a></h3><ul><li>5.1 算术运算符 <ul><li>5.1.1 字符+操作</li><li>5.1.2 字符串+操作</li></ul></li><li>5.2 赋值运算符</li><li>5.3 逻辑运算符</li></ul><h3 id="基础输入与随机数" tabindex="-1">基础输入与随机数 <a class="header-anchor" href="#基础输入与随机数" aria-label="Permalink to &quot;基础输入与随机数&quot;">​</a></h3><p><strong>数据输入 Scanner 类</strong></p><ul><li><strong>Scanner 类</strong>：获取用户的输入。</li><li><strong>引入后创建对象</strong>：<code>Scanner sc = new Scanner(System.in);</code></li><li><strong>接收数据</strong>（这一步就会让用户进行输入，输入完成后才对 x 赋值）： <ul><li><code>int x = sc.nextInt();</code></li></ul></li></ul><p><strong>随机数 Random 类</strong></p><ul><li><strong>引入后创建对象</strong>：<code>Random r = new Random();</code></li><li><strong>生产随机数</strong>： <ul><li><code>int num = r.nextInt(10);</code></li><li><strong>随机范围</strong>：0 ~ 传入数值-1</li></ul></li></ul><h2 id="三、数组" tabindex="-1">三、数组 <a class="header-anchor" href="#三、数组" aria-label="Permalink to &quot;三、数组&quot;">​</a></h2><h3 id="数组初始化" tabindex="-1">数组初始化 <a class="header-anchor" href="#数组初始化" aria-label="Permalink to &quot;数组初始化&quot;">​</a></h3><ul><li>1.1 动态初始化</li><li>1.2 内存分配</li><li>1.3 静态初始化</li></ul><h2 id="四、方法" tabindex="-1">四、方法 <a class="header-anchor" href="#四、方法" aria-label="Permalink to &quot;四、方法&quot;">​</a></h2><h3 id="方法在代码中定义" tabindex="-1">方法在代码中定义 <a class="header-anchor" href="#方法在代码中定义" aria-label="Permalink to &quot;方法在代码中定义&quot;">​</a></h3><h3 id="参数的注意事项" tabindex="-1">参数的注意事项 <a class="header-anchor" href="#参数的注意事项" aria-label="Permalink to &quot;参数的注意事项&quot;">​</a></h3><h3 id="带返回值的方式定义" tabindex="-1">带返回值的方式定义 <a class="header-anchor" href="#带返回值的方式定义" aria-label="Permalink to &quot;带返回值的方式定义&quot;">​</a></h3><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><h3 id="方法重载" tabindex="-1">方法重载 <a class="header-anchor" href="#方法重载" aria-label="Permalink to &quot;方法重载&quot;">​</a></h3><h3 id="方法参数类型问题" tabindex="-1">方法参数类型问题 <a class="header-anchor" href="#方法参数类型问题" aria-label="Permalink to &quot;方法参数类型问题&quot;">​</a></h3>',34)])])}const f=l(d,[["render",i]]);export{u as __pageData,f as default};
